export const interactionText = (language: LanguageCode, value: string) => {
  const index = interactionKeys.indexOf(value);
  return index < 0
    ? (interactionExtras[language][value] || voiceMessageCopy[language][value] || voiceRetryCopy[language][value] || value)
    : interactionValues[language][index];
};
